      ctx.lineTo(80, 260);
      ctx.lineTo(130, 280);
      ctx.lineTo(160, 200);
      ctx.lineTo(160, 420);
      ctx.lineTo(352, 420);
      ctx.lineTo(352, 200);
      ctx.lineTo(382, 280);
      ctx.lineTo(432, 260);
      ctx.lineTo(392, 150);
      ctx.lineTo(332, 100);
